import {pickupGeometry} from './pickup-geometry.js?v=detail18';
import * as T from './three.module.js';
import {createFarmVehicle as fallbackVehicle} from './vehicle-fallback.js?v=vehicles14';
import {GLTFLoader} from './vendor/GLTFLoader.js';
const cache=new Map();
export function loadVehicleAsset(type){
 if(!cache.has(type)){const name=type==='tractor'?'row-crop-tractor':'county-pickup';const url=new URL('./models/vehicles/'+name+'.glb',import.meta.url).href;const request=fetch(url,{signal:AbortSignal.timeout(18000)}).then(r=>{if(!r.ok)throw Error('HTTP '+r.status);return r.arrayBuffer();}).then(b=>new GLTFLoader().parseAsync(b,''));cache.set(type,request);request.catch(()=>cache.delete(type));}return cache.get(type);
}
// Native metre-scale geometry and authored axle pivots: no skinning or mesh stretching.
export function createFarmVehicle(type,color='#6c9696',{asset=null,load=true,style='touring'}={}){
 const root=new T.Group(),wheels=[],steering=[],tool=new T.Group();root.name=type==='tractor'?'Detailed row-crop tractor':'Detailed county pickup';
 root.add(tool);tool.name='Three-point field cultivator';if(type==='tractor'){const steel=new T.MeshStandardMaterial({color:'#626d69',metalness:.65,roughness:.48}),paint=new T.MeshStandardMaterial({color:'#a34e37',metalness:.3,roughness:.6});const frame=new T.Mesh(new T.BoxGeometry(2.3,.16,.7),paint);frame.position.set(0,.55,-2.85);tool.add(frame);for(let i=0;i<5;i++){const x=-.95+i*.475,curve=new T.CatmullRomCurve3([new T.Vector3(x,.55,-2.8),new T.Vector3(x,.3,-3.15),new T.Vector3(x,.12,-3.28)]),tine=new T.Mesh(new T.TubeGeometry(curve,6,.045,5,false),steel);tool.add(tine);}for(const side of [-1,1]){const a=new T.Vector3(side*.7,.55,-2.8),b=new T.Vector3(side*.25,1.1,-2.1),v=b.clone().sub(a),arm=new T.Mesh(new T.CylinderGeometry(.06,.06,v.length(),6),steel);arm.position.copy(a.add(b).multiplyScalar(.5));arm.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),v.normalize());tool.add(arm);}}
 const cargo=new T.Group();cargo.name='Delivery cargo';root.add(cargo);cargo.visible=false;
 const crateMat=new T.MeshStandardMaterial({color:'#b99361',roughness:.85});
 for(let i=0;i<4;i++){const m=new T.Mesh(new T.BoxGeometry(.65,.55,.65),crateMat);m.position.set((i%2-.5)*.75,1,-1.2-Math.floor(i/2)*.7);cargo.add(m);}
 let towing=false;let status='loading',error='',loaded=false,fallback=null;
 function install(gltf){const model=gltf.scene.clone(true);model.name='Native vehicle geometry';const wheelNodes=[];model.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true;const originals=Array.isArray(o.material)?o.material:[o.material];const styled=originals.map(m=>{const n=m.clone(),name=(n.name||'').toLowerCase();n.envMapIntensity=.8;if(name.includes('paint')){n.color.set(type==='tractor'?'#487b43':color);n.metalness=.22;n.roughness=.45;}if(name.includes('glass')){n.color.set('#839ca6');n.metalness=.12;n.roughness=.2;}if(name.includes('rubber')||name==='dark'){n.roughness=.94;n.metalness=0;}return n;});o.material=Array.isArray(o.material)?styled:styled[0];}if(/^wheel-(front|rear)-(left|right)$/.test(o.name))wheelNodes.push(o);});for(const o of wheelNodes){const radius=type==='tractor'?(o.name.includes('rear')?.82:.58):.37;const pivot=new T.Group();pivot.position.copy(o.position);pivot.quaternion.copy(o.quaternion);o.parent.add(pivot);pivot.add(o);o.position.set(0,0,0);o.quaternion.identity();wheels.push({spin:o,pivot,radius});if(o.name.includes('front'))steering.push(pivot);}
 const bounds=new T.Box3().setFromObject(model);model.position.y-=bounds.min.y;root.add(model);loaded=true;status='3D loaded';return model;}
 const ready=asset?Promise.resolve(install(asset)):type==='pickup'&&load?Promise.resolve(install(pickupGeometry(style))):load?loadVehicleAsset(type).then(install).catch(e=>{status='Fallback · load failed';error=e.message;fallback=fallbackVehicle(type,color);root.add(fallback.root);console.error('Vehicle model failed:',type,e);return null;}):Promise.resolve(null);
 return {root,wheels,cargo,ready,setTowing(value){towing=value;tool.visible=type==='tractor'&&!value;},get status(){return status;},get error(){return error;},update(distance,turn=0,hasCargo=false,working=false){tool.position.y=working?0:.25;if(fallback)fallback.update(distance,-turn,hasCargo);for(const w of wheels)w.spin.rotation.x+=distance/w.radius;for(const p of steering)p.rotation.y=-turn*.38;cargo.visible=type==='pickup'&&hasCargo&&loaded;}};
}
